// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import {SSTORE2} from "solady/src/utils/SSTORE2.sol";
import {LibString} from "solady/src/utils/LibString.sol";
import {LibCWIA} from "solady/src/utils/legacy/LibCWIA.sol";
import {SafeTransferLib} from "solady/src/utils/SafeTransferLib.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {PausableUpgradeable, Initializable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {IPropositionMarketToken, IPropositionMarketFactory} from "./interfaces/IPropositionMarketFactory.sol";

struct MarketSettings {
    address[] tokenDataList;
}

struct TokenSettings {
    address owner;
    string name;
    string symbol;
}

struct FactorySettings {
    address feeRecipient;
    uint256 platformFee;
}

/// @custom:security-contact draco@nextmate.ai
contract PropositionMarketFactory is
    Initializable,
    PausableUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    IPropositionMarketFactory
{
    using LibCWIA for *;
    using LibString for *;
    using SafeTransferLib for *;

    /// @custom:storage-location erc7201:PropositionMarketFactoryStorage
    struct PropositionMarketFactoryStorage {
        string version;
        address implementation;
        address tokenImplementation;
        FactorySettings factorySettings;
    }

    bytes32 public constant POOL_ROLE = keccak256("POOL_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant CREATOR_ROLE = keccak256("CREATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // keccak256(abi.encode(uint256(keccak256("PropositionMarketFactoryStorage")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant _PROPOSITION_MARKET_FACTORY_STORAGE =
        0xca2fe85550dc2df9d90e90f9056a5a27c19809a8536e8712d438bd80180ec500;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _defaultAdmin,
        address _implementation,
        address _tokenImplementation,
        FactorySettings calldata _factorySettings
    ) external initializer {
        PropositionMarketFactoryStorage storage $ = _getPropositionMarketFactoryStorage();

        $.version = "1.0.0";
        $.implementation = _implementation;
        $.tokenImplementation = _tokenImplementation;
        $.factorySettings = _factorySettings;

        __Pausable_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, _defaultAdmin);
        _grantRole(CREATOR_ROLE, _defaultAdmin);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function setPlatformFee(uint256 newPlatformFee) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _getPropositionMarketFactoryStorage().factorySettings.platformFee = newPlatformFee;
    }

    function setFeeRecipient(address newFeeRecipient) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _getPropositionMarketFactoryStorage().factorySettings.feeRecipient = newFeeRecipient;
    }

    function setImplementation(address newImplementation) external onlyRole(UPGRADER_ROLE) {
        _getPropositionMarketFactoryStorage().implementation = newImplementation;
    }

    function setTokenImplementation(address newTokenImplementation) external onlyRole(UPGRADER_ROLE) {
        _getPropositionMarketFactoryStorage().tokenImplementation = newTokenImplementation;
    }

    function setImplementationVersion(string calldata version) external onlyRole(UPGRADER_ROLE) {
        _getPropositionMarketFactoryStorage().version = version;
    }

    function emitEventTrade(
        address token,
        address trader,
        int256 tokenAmount,
        uint256 executionPrice
    ) external onlyRole(POOL_ROLE) {
        emit Trade(msg.sender, token, trader, tokenAmount, executionPrice);
    }

    function createContracts(
        TokenSettings[] memory tokenSettings,
        string calldata poolTitle,
        address payToken,
        address manager
    ) external returns (address pool) {
        PropositionMarketFactoryStorage storage $ = _getPropositionMarketFactoryStorage();

        address[] memory addressList = new address[](tokenSettings.length + 3);
        for (uint256 i = 0; i < tokenSettings.length; ) {
            (bytes memory tokenSettingsData, bytes32 tokenSettingsSalt) = _encodeImmutableArgs(tokenSettings[i]);
            addressList[i] = $.tokenImplementation.cloneDeterministic(tokenSettingsData, tokenSettingsSalt);
            unchecked {
                ++i;
            }
        }
        addressList[tokenSettings.length] = address(this);
        addressList[tokenSettings.length + 1] = manager;
        addressList[tokenSettings.length + 2] = payToken;

        bytes memory addressListData = _encodeImmutableArgs(
            SSTORE2.writeCounterfactual(abi.encode(addressList), keccak256(abi.encode(addressList))),
            tokenSettings.length,
            poolTitle
        );
        pool = $.implementation.cloneDeterministic(addressListData, keccak256(abi.encode(addressListData)));

        _grantRole(POOL_ROLE, pool);

        for (uint256 i = 0; i < tokenSettings.length; ) {
            IPropositionMarketToken(addressList[i]).transferOwnership(pool);
            unchecked {
                ++i;
            }
        }
        emit CreatePool(pool);
        return pool;
    }

    function predictInitCodeHash(
        TokenSettings[] calldata tokenSettings,
        string calldata poolTitle,
        address payToken,
        address manager
    ) external view virtual returns (bytes32) {
        address[] memory oldList = predictDeterministicAddress(tokenSettings);
        uint256 len = oldList.length;

        address[] memory addressList = new address[](len + 3);

        for (uint256 i = 0; i < len; ) {
            addressList[i] = oldList[i];
            ++i;
        }

        addressList[len] = address(this);
        addressList[len + 1] = manager;
        addressList[len + 2] = payToken;

        bytes memory addressListData = _encodeImmutableArgs(
            SSTORE2.predictCounterfactualAddress(abi.encode(addressList), keccak256(abi.encode(addressList))),
            tokenSettings.length,
            poolTitle
        );

        return _getPropositionMarketFactoryStorage().implementation.initCodeHash(addressListData);
    }

    function getPlatformFee() external view returns (uint256) {
        return _getPropositionMarketFactoryStorage().factorySettings.platformFee;
    }

    function getFeeRecipient() external view returns (address) {
        return _getPropositionMarketFactoryStorage().factorySettings.feeRecipient;
    }

    function getImplementation() external view returns (address) {
        return _getPropositionMarketFactoryStorage().implementation;
    }

    function getTokenImplementation() external view returns (address) {
        return _getPropositionMarketFactoryStorage().tokenImplementation;
    }

    function getPoolVersion() external view returns (string memory) {
        return _getPropositionMarketFactoryStorage().version;
    }

    /**
     * @dev Get predict deterministic address
     */
    function predictDeterministicAddress(
        TokenSettings[] calldata tokenSettings
    ) public view virtual returns (address[] memory addressList) {
        PropositionMarketFactoryStorage storage $ = _getPropositionMarketFactoryStorage();

        unchecked {
            addressList = new address[](tokenSettings.length);

            for (uint256 i = 0; i < tokenSettings.length; ) {
                (bytes memory data, bytes32 salt) = _encodeImmutableArgs(tokenSettings[i]);
                addressList[i] = $.tokenImplementation.predictDeterministicAddress(data, salt, address(this));
                ++i;
            }
        }
    }

    function predictDeterministicAddress(
        TokenSettings[] calldata tokenSettings,
        string calldata poolTitle,
        address payToken,
        address manager
    ) public view virtual returns (address pool) {
        unchecked {
            address[] memory oldList = predictDeterministicAddress(tokenSettings);
            uint256 len = oldList.length;

            address[] memory addressList = new address[](len + 3);

            for (uint256 i = 0; i < len; ) {
                addressList[i] = oldList[i];
                ++i;
            }

            addressList[len] = address(this);
            addressList[len + 1] = manager;
            addressList[len + 2] = payToken;

            bytes memory addressListData = _encodeImmutableArgs(
                SSTORE2.predictCounterfactualAddress(abi.encode(addressList), keccak256(abi.encode(addressList))),
                tokenSettings.length,
                poolTitle
            );
            pool = _getPropositionMarketFactoryStorage().implementation.predictDeterministicAddress(
                addressListData,
                keccak256(abi.encode(addressListData)),
                address(this)
            );
        }
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    function _encodeImmutableArgs(TokenSettings memory args) internal view virtual returns (bytes memory, bytes32) {
        unchecked {
            return (
                abi.encodePacked(args.owner, args.name.toSmallString(), args.symbol.toSmallString()),
                keccak256(abi.encode(args.owner, args.name, args.symbol))
            );
        }
    }

    function _encodeImmutableArgs(
        address dataPointer,
        uint256 length,
        string calldata poolTitle
    ) internal view virtual returns (bytes memory) {
        unchecked {
            return
                abi.encodePacked(
                    abi.encodePacked(uint64(length)),
                    dataPointer,
                    poolTitle.toSmallString(),
                    _getPropositionMarketFactoryStorage().version.toSmallString()
                );
        }
    }

    /**
     * @dev Get PropositionMarketFactoryStorage data
     */
    function _getPropositionMarketFactoryStorage() private pure returns (PropositionMarketFactoryStorage storage $) {
        assembly {
            $.slot := _PROPOSITION_MARKET_FACTORY_STORAGE
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import {Price} from "price/src/Price.sol";
import {SSTORE2} from "solady/src/utils/SSTORE2.sol";
import {CWIA} from "solady/src/utils/legacy/CWIA.sol";
import {LibString} from "solady/src/utils/LibString.sol";
import {LibString} from "solady/src/utils/LibString.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {FixedPointMathLib} from "solady/src/utils/FixedPointMathLib.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IPropositionMarketToken, IPropositionMarketPool, IPropositionMarketFactory} from "./interfaces/IPropositionMarketPool.sol";

contract PropositionMarketPool is IPropositionMarketPool, CWIA, ReentrancyGuard {
    using Price for *;
    using LibString for *;
    using FixedPointMathLib for *;

    uint256 public totalPlatformFee;
    bool public paused;
    mapping(address => uint256) public optionTvl;

    modifier onlyManager() {
        if (getManagerAddress() != msg.sender) revert OwnableUnauthorizedAccount(msg.sender);
        _;
    }
    modifier whenNotPaused() {
        if (!paused) revert EnforcedPause();
        _;
    }

    modifier timeCheck(uint256 expireTimestamp) {
        if (expireTimestamp < block.timestamp) revert TimeoutProhibition();
        _;
    }

    modifier tokenAmountCheck(uint256 tokenAmount) {
        if (tokenAmount == 0) revert ZeroQuantityError();
        _;
    }

    function buy(
        IPropositionMarketToken token,
        uint256 tokenAmount,
        uint256 maxUsdtProvided,
        uint256 expireTimestamp
    ) external nonReentrant timeCheck(expireTimestamp) tokenAmountCheck(tokenAmount) returns (uint256) {
        // calculate price and amount
        (uint256 tokenSupply, uint256 supplyOther) = _getSupplies(address(token));
        uint256 tokenPrice = Price.getExecutionPrice(tokenSupply, supplyOther, int256(tokenAmount));
        uint256 usdtAmount = tokenPrice.mulWad(tokenAmount);

        // calculate platform fee
        uint256 platformFee = usdtAmount.mulWad(getPlatformFee());
        totalPlatformFee += platformFee;

        // transfer usdt from sender
        uint256 usdtNetAmount = usdtAmount.rawAdd(platformFee);
        if (usdtNetAmount > maxUsdtProvided) revert SlippageFailed(usdtNetAmount, maxUsdtProvided);
        if (!getPayTokenAddress().transferFrom(msg.sender, address(this), usdtNetAmount)) revert PaymentFailed();

        // update tvl
        optionTvl[address(token)] += usdtNetAmount;

        // mint and transfer token to sender
        _mintAndTransfer(token, tokenAmount);

        // emit event
        IPropositionMarketFactory(getFactoryAddress()).emitEventTrade(
            address(token),
            msg.sender,
            int256(tokenAmount),
            tokenPrice
        );

        return tokenAmount;
    }

    function buy(
        IPropositionMarketToken token,
        uint256 tokenAmount,
        uint256 usdtProvided,
        uint256 minTokenReceived,
        uint256 expireTimestamp
    ) external nonReentrant timeCheck(expireTimestamp) tokenAmountCheck(usdtProvided) returns (uint256) {
        // calculate price and amount
        (uint256 tokenSupply, uint256 supplyOther) = _getSupplies(address(token));

        uint256 tokenPrice = tokenSupply.getExecutionPrice(supplyOther, int256(tokenAmount));
        uint256 usdtAmount = tokenPrice.mulWad(tokenAmount);
        uint256 usdtNetAmount = usdtAmount.divWad(1 ether.rawSub(getPlatformFee()));

        // check usdt provided
        if (
            usdtNetAmount > usdtProvided ||
            (usdtProvided.rawSub(usdtNetAmount) > (usdtProvided / Price.DEFAULT_APPROXIMATION_PRECISION))
        ) {
            // Recalculate token amount and execution price by approximation
            (uint256 newTokenAmount, uint256 executionPrice) = Price.approximateExecutionPrice(
                tokenSupply,
                supplyOther,
                usdtAmount
            );

            // check slippage
            if (newTokenAmount < minTokenReceived) revert SlippageFailed(newTokenAmount, minTokenReceived);

            // Update values with new token amount
            tokenAmount = newTokenAmount;
            tokenPrice = executionPrice;
            usdtAmount = tokenPrice.mulWad(tokenAmount);
            usdtNetAmount = usdtAmount.divWad(1 ether.rawSub(getPlatformFee()));
        }

        // calculate platform fee
        totalPlatformFee += usdtNetAmount.rawSub(usdtAmount);

        // transfer usdt from sender
        if (!getPayTokenAddress().transferFrom(msg.sender, address(this), usdtNetAmount)) revert PaymentFailed();

        // update tvl
        optionTvl[address(token)] += usdtAmount;

        // mint and transfer token to sender
        if (tokenAmount < minTokenReceived) revert SlippageFailed(tokenAmount, minTokenReceived);

        _mintAndTransfer(token, tokenAmount);

        // emit event
        IPropositionMarketFactory(getFactoryAddress()).emitEventTrade(
            address(token),
            msg.sender,
            int256(tokenAmount),
            tokenPrice
        );

        return tokenAmount;
    }

    function sell(
        IPropositionMarketToken token,
        uint256 tokenAmount,
        uint256 minUsdtReceived,
        uint256 expireTimestamp
    ) external nonReentrant timeCheck(expireTimestamp) tokenAmountCheck(tokenAmount) returns (uint256) {
        // calculate price and amount
        (uint256 tokenSupply, uint256 supplyOther) = _getSupplies(address(token));
        uint256 tokenPrice = tokenSupply.getExecutionPrice(supplyOther, int256(tokenAmount));
        uint256 usdtAmount = tokenPrice.mulWad(tokenAmount);

        // calculate platform fee
        uint256 platformFee = usdtAmount.mulWad(getPlatformFee());
        totalPlatformFee += platformFee;
        uint256 usdtNetAmount = usdtAmount.rawSub(platformFee);

        // check minimum received amount
        if (usdtNetAmount < minUsdtReceived) revert SlippageFailed(usdtNetAmount, minUsdtReceived);

        // transfer token from sender and burn it
        if (!token.transferFrom(msg.sender, address(this), tokenAmount)) revert PaymentFailed();
        token.burn(address(this), tokenAmount);

        // update tvl
        optionTvl[address(token)] -= usdtNetAmount;

        // transfer usdt to sender
        if (!getPayTokenAddress().transfer(msg.sender, usdtNetAmount)) revert PaymentFailed();

        // emit event
        IPropositionMarketFactory(getFactoryAddress()).emitEventTrade(
            address(token),
            msg.sender,
            -int256(tokenAmount),
            tokenPrice
        );

        return usdtNetAmount;
    }

    function receivePlatformFee(address receiver) external onlyManager {
        if (totalPlatformFee == 0) revert InsufficientBalance();
        totalPlatformFee = 0;

        if (!getPayTokenAddress().transfer(receiver, totalPlatformFee)) revert PaymentFailed();
    }

    function pausedPool() external onlyManager {
        if (paused) revert EnforcedPause();
        emit Paused(paused = !paused);
    }

    function getFeeRecipient() external view returns (address) {
        return IPropositionMarketFactory(getFactoryAddress()).getFeeRecipient();
    }

    function getOptionListLength() external pure returns (uint256) {
        return _getArgUint64(0);
    }

    function calculateSpotPrice(uint256 supply, uint256 supplyOther) external pure returns (uint256) {
        return Price.getSpotPrice(supply, supplyOther);
    }

    function calculateExecutionPrice(
        uint256 supply,
        uint256 supplyOther,
        int256 amountChanged
    ) external pure returns (uint256) {
        return Price.getExecutionPrice(supply, supplyOther, amountChanged);
    }

    function getOptionList() public view returns (address[] memory) {
        unchecked {
            address dataPointer = _getArgAddress(8);
            address[] memory fullList = abi.decode(SSTORE2.read(dataPointer), (address[]));

            address[] memory sliced = new address[](_getArgUint64(0));
            for (uint256 i = 0; i < _getArgUint64(0); ++i) {
                sliced[i] = fullList[i];
            }

            return sliced;
        }
    }

    function getFactoryAddress() public view returns (address) {
        unchecked {
            address dataPointer = _getArgAddress(8);
            address[] memory fullList = abi.decode(SSTORE2.read(dataPointer), (address[]));
            return fullList[fullList.length - 3];
        }
    }

    function getManagerAddress() public view returns (address) {
        unchecked {
            address dataPointer = _getArgAddress(8);
            address[] memory fullList = abi.decode(SSTORE2.read(dataPointer), (address[]));
            return fullList[fullList.length - 2];
        }
    }

    function getPayTokenAddress() public view returns (IERC20) {
        unchecked {
            address dataPointer = _getArgAddress(8);
            address[] memory fullList = abi.decode(SSTORE2.read(dataPointer), (address[]));
            return IERC20(fullList[fullList.length - 1]);
        }
    }

    function getPlatformFee() public view returns (uint256) {
        return IPropositionMarketFactory(getFactoryAddress()).getPlatformFee();
    }

    function getSpotPrice(address token) public view returns (uint256) {
        (uint256 supply, uint256 supplyOther) = _getSupplies(token);
        return Price.getSpotPrice(supply, supplyOther);
    }

    function getExecutionPrice(address token, int256 amountChanged) public view returns (uint256) {
        (uint256 supply, uint256 supplyOther) = _getSupplies(token);
        return Price.getExecutionPrice(supply, supplyOther, amountChanged);
    }

    function getApproximatePrice(
        address token,
        uint256 usdtAmount,
        uint256 precision,
        uint256 maxIteration
    ) public view returns (uint256 tokenAmount, uint256 avgPrice) {
        (uint256 supply, uint256 supplyOther) = _getSupplies(token);
        (tokenAmount, avgPrice) = Price.approximateExecutionPrice(
            supply,
            supplyOther,
            usdtAmount,
            precision,
            maxIteration
        );
    }

    function getApproximatePrice(
        address token,
        uint256 usdtAmount
    ) public view returns (uint256 tokenAmount, uint256 avgPrice) {
        (uint256 supply, uint256 supplyOther) = _getSupplies(token);
        (tokenAmount, avgPrice) = Price.approximateExecutionPrice(
            supply,
            supplyOther,
            usdtAmount,
            Price.DEFAULT_APPROXIMATION_PRECISION,
            Price.DEFAULT_MAX_ITERATIONS
        );
    }

    function getPoolTitle() public pure returns (string memory) {
        unchecked {
            return _getArgBytes32(28).fromSmallString();
        }
    }

    function getPoolVersion() public pure returns (string memory) {
        unchecked {
            return _getArgBytes32(60).fromSmallString();
        }
    }

    function _mintAndTransfer(IPropositionMarketToken token, uint256 tokenAmount) internal {
        token.mint(address(this), tokenAmount);
        if (!token.transfer(msg.sender, tokenAmount)) revert PaymentFailed();
    }

    function _getSupplies(address token) internal view returns (uint256 supply, uint256 supplyOther) {
        supply = IERC20(token).totalSupply();
        address[] memory optionList = getOptionList();
        bool find = false;

        for (uint256 i = 0; i < optionList.length; ++i) {
            if (optionList[i] != token) {
                supplyOther += IERC20(optionList[i]).totalSupply();
            } else {
                find = true;
            }
        }

        if (!find) revert InvalidToken();
    }
}

